def grant(apps, schema_editor):
    """Les rôles des écoles existantes reçoivent les droits des présences (lot 10)."""
    Role = apps.get_model("accounts", "Role")
    for role in Role._base_manager.all():
        added = [
            code
            for marker, codes in GRANTS.items()
            if marker in role.permissions
            for code in codes
            if code not in role.permissions
        ]
        if added:
            role.permissions = [*role.permissions, *dict.fromkeys(added)]
            role.save(update_fields=["permissions"])


